import { useProducts } from '../hooks/useProducts'
import ProductCard from '../components/ProductCard'

function SkeletonCard() {
  return (
    <div className="rounded-2xl overflow-hidden shadow-md border border-gray-200 bg-white animate-pulse">
      <div style={{ paddingTop: '75%' }} className="relative bg-gray-200 w-full" />
      <div className="p-4 flex flex-col gap-3">
        <div className="h-4 bg-gray-200 rounded w-3/4" />
        <div className="h-3 bg-gray-200 rounded w-full" />
        <div className="h-3 bg-gray-200 rounded w-5/6" />
        <div className="flex justify-between items-center mt-2">
          <div className="h-5 bg-gray-200 rounded w-16" />
          <div className="h-8 bg-gray-200 rounded-xl w-24" />
        </div>
      </div>
    </div>
  )
}

export default function Gallery() {
  const { products, loading, error } = useProducts()
  const [search, setSearch] = useState('')
  const [activePills, setActivePills] = useState([])

  // Derive unique tags from all products in a stable sorted order
  const allTags = useMemo(() => {
    const tagSet = new Set()
    products.forEach(p => (p.tags ?? []).forEach(t => tagSet.add(t)))
    return Array.from(tagSet).sort()
  }, [products])

  // Toggle a tag pill on/off
  function togglePill(tag) {
    setActivePills(prev =>
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    )
  }

  function clearAll() {
    setSearch('')
    setActivePills([])
  }

  // Filter products in memory — no re-fetch
  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase()
    return products.filter(p => {
      // Check all active pills: product must include every active tag
      const matchesPills =
        activePills.length === 0 ||
        activePills.every(pill => (p.tags ?? []).includes(pill))

      if (!matchesPills) return false
      if (!query) return true

      // Case-insensitive match against name, description, and any tag
      const inName = p.name?.toLowerCase().includes(query)
      const inDesc = p.description?.toLowerCase().includes(query)
      const inTags = (p.tags ?? []).some(t => t.toLowerCase().includes(query))
      return inName || inDesc || inTags
    })
  }, [products, search, activePills])

  const hasActiveFilters = search.trim() !== '' || activePills.length > 0

  return (
    <main className="px-4 py-8 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Our Products</h1>

      {/* Search + filter controls */}
      <div className="mb-6 flex flex-col gap-3">
        <div className="flex items-center gap-2">
          <input
            type="search"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search by name, description or tag…"
            aria-label="Search products"
            className="flex-1 rounded-xl border border-gray-300 px-4 py-2 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
          />
          {hasActiveFilters && (
            <button
              onClick={clearAll}
              className="text-sm text-indigo-600 hover:text-indigo-800 font-medium whitespace-nowrap"
            >
              Clear all
            </button>
          )}
        </div>

        {/* Tag pill filters */}
        {allTags.length > 0 && (
          <div className="flex flex-wrap gap-2" role="group" aria-label="Filter by tag">
            {allTags.map(tag => {
              const active = activePills.includes(tag)
              return (
                <button
                  key={tag}
                  onClick={() => togglePill(tag)}
                  aria-pressed={active}
                  className={`text-xs font-medium px-3 py-1 rounded-full border transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-indigo-400 ${
                    active
                      ? 'bg-indigo-600 text-white border-indigo-600'
                      : 'bg-white text-gray-600 border-gray-300 hover:border-indigo-400 hover:text-indigo-600'
                  }`}
                >
                  {tag}
                </button>
              )
            })}
          </div>
        )}
      </div>

      {error && (
        <div className="rounded-xl bg-red-50 border border-red-200 text-red-700 px-5 py-4 mb-6">
          <p className="font-medium">Failed to load products</p>
          <p className="text-sm mt-1">{error}</p>
        </div>
      )}

      {/* Responsive grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading
          ? Array.from({ length: 6 }).map((_, i) => <SkeletonCard key={i} />)
          : filtered.map(product => (
              <ProductCard key={product.id} product={product} />
            ))}
      </div>

      {/* Empty state */}
      {!loading && !error && filtered.length === 0 && (
        <div className="text-center text-gray-500 py-16">
          {hasActiveFilters ? (
            <>
              <p className="text-lg font-medium">No products match your filters.</p>
              <p className="text-sm mt-1">
                <button onClick={clearAll} className="text-indigo-600 hover:underline">
                  Clear all filters
                </button>
              </p>
            </>
          ) : (
            <>
              <p className="text-lg font-medium">No products available yet.</p>
              <p className="text-sm mt-1">Check back soon!</p>
            </>
          )}
        </div>
      )}
    </main>
  )
}
