import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import Stripe from 'https://esm.sh/stripe@13';

// --- Types ---

interface RequestItem {
  product_id: string;
  quantity: number;
}

interface CustomerInfo {
  name: string;
  email: string;
  street: string;
  city: string;
  postal_code: string;
  country: string;
}

interface CreatePaymentIntentRequest {
  items: RequestItem[];
  customer: CustomerInfo;
}

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  image_url: string;
  tags: string[];
  is_available: boolean;
}

// --- Helpers ---

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function errorResponse(message: string, status = 400): Response {
  return jsonResponse({ error: message }, status);
}

function validateRequest(body: unknown): { data: CreatePaymentIntentRequest | null; error: string | null } {
  if (!body || typeof body !== 'object') {
    return { data: null, error: 'Request body must be a JSON object' };
  }

  const req = body as Record<string, unknown>;

  if (!Array.isArray(req.items) || req.items.length === 0) {
    return { data: null, error: 'items must be a non-empty array' };
  }

  for (const item of req.items) {
    if (!item || typeof item !== 'object') {
      return { data: null, error: 'Each item must be an object' };
    }
    const i = item as Record<string, unknown>;
    if (typeof i.product_id !== 'string' || !i.product_id) {
      return { data: null, error: 'Each item must have a valid product_id string' };
    }
    if (typeof i.quantity !== 'number' || i.quantity < 1 || !Number.isInteger(i.quantity)) {
      return { data: null, error: 'Each item must have a positive integer quantity' };
    }
  }

  const c = req.customer as Record<string, unknown> | undefined;
  if (!c || typeof c !== 'object') {
    return { data: null, error: 'customer object is required' };
  }

  const requiredCustomerFields = ['name', 'email', 'street', 'city', 'postal_code', 'country'] as const;
  for (const field of requiredCustomerFields) {
    if (typeof c[field] !== 'string' || !(c[field] as string).trim()) {
      return { data: null, error: `customer.${field} is required` };
    }
  }

  return { data: body as CreatePaymentIntentRequest, error: null };
}

// --- Main handler ---

serve(async (req: Request): Promise<Response> => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return errorResponse('Method not allowed', 405);
  }

  // --- Parse body ---
  let rawBody: unknown;
  try {
    rawBody = await req.json();
  } catch {
    return errorResponse('Invalid JSON body');
  }

  // --- Validate shape ---
  const { data: validatedBody, error: validationError } = validateRequest(rawBody);
  if (validationError || !validatedBody) {
    return errorResponse(validationError ?? 'Invalid request');
  }

  const { items, customer } = validatedBody;

  // --- Init clients (done after validation so we skip env lookups on bad input) ---
  const supabaseUrl = Deno.env.get('SUPABASE_URL');
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  const stripeSecret = Deno.env.get('STRIPE_SECRET_KEY');

  if (!supabaseUrl || !serviceRoleKey || !stripeSecret) {
    return errorResponse('Server misconfiguration: missing environment variables', 500);
  }

  // Service role client bypasses RLS — required for trusted server-side writes
  const supabase = createClient(supabaseUrl, serviceRoleKey);
  const stripe = new Stripe(stripeSecret, { apiVersion: '2023-10-16' });

  // --- Step 1: Fetch all referenced products in a single query ---
  const productIds = items.map((i) => i.product_id);

  const { data: products, error: fetchError } = await supabase
    .from('products')
    .select('id, name, description, price, image_url, tags, is_available')
    .in('id', productIds);

  if (fetchError) {
    return errorResponse(`Failed to fetch products: ${fetchError.message}`, 500);
  }

  // --- Step 2: Verify every requested product_id exists ---
  const productMap = new Map<string, Product>((products ?? []).map((p: Product) => [p.id, p]));

  for (const item of items) {
    if (!productMap.has(item.product_id)) {
      return errorResponse(`Product not found: ${item.product_id}`);
    }
  }

  // --- Step 3: Verify every product is available ---
  for (const item of items) {
    const product = productMap.get(item.product_id)!;
    if (!product.is_available) {
      return errorResponse(`Product is not available: ${item.product_id}`);
    }
  }

  // --- Step 4: Calculate total from DB prices only (never trust client) ---
  const totalCents = items.reduce((sum, item) => {
    const product = productMap.get(item.product_id)!;
    return sum + product.price * item.quantity;
  }, 0);

  if (totalCents <= 0) {
    return errorResponse('Calculated total must be greater than zero');
  }

  // --- Step 5: Create Stripe PaymentIntent ---
  let paymentIntent: Stripe.PaymentIntent;
  try {
    paymentIntent = await stripe.paymentIntents.create({
      amount: totalCents,
      currency: 'eur',
      // Store email for Stripe dashboard visibility
      receipt_email: customer.email,
      metadata: {
        customer_name: customer.name,
        customer_email: customer.email,
      },
    });
  } catch (stripeError) {
    const message = stripeError instanceof Error ? stripeError.message : 'Unknown Stripe error';
    return errorResponse(`Stripe error: ${message}`, 500);
  }

  // --- Step 6: Insert orders row using RPC to keep mutations server-side ---
  const { data: orderRows, error: orderError } = await supabase
    .rpc('insert_order', {
      p_stripe_payment_id: paymentIntent.id,
      p_status: 'order_received',
      p_total: totalCents,
      p_customer_name: customer.name,
      p_customer_email: customer.email,
      p_shipping_street: customer.street,
      p_shipping_city: customer.city,
      p_shipping_postal_code: customer.postal_code,
      p_shipping_country: customer.country,
    });

  if (orderError || !orderRows || orderRows.length === 0) {
    // PI was created — log the orphaned PI id so ops can reconcile
    console.error('Order insert failed after PI creation. Orphaned PI:', paymentIntent.id, orderError);
    return errorResponse(`Failed to create order: ${orderError?.message ?? 'no rows returned'}`, 500);
  }

  const orderId: string = orderRows[0].id;

  // --- Step 7: Insert one order_items row per item ---
  const orderItemsPayload = items.map((item) => ({
    order_id: orderId,
    product_id: item.product_id,
    quantity: item.quantity,
    // price_at_purchase locked to DB value at time of purchase — never client value
    price_at_purchase: productMap.get(item.product_id)!.price,
  }));

  const { error: itemsError } = await supabase
    .rpc('insert_order_items', { p_items: orderItemsPayload });

  if (itemsError) {
    console.error('order_items insert failed. order_id:', orderId, 'PI:', paymentIntent.id, itemsError);
    return errorResponse(`Failed to create order items: ${itemsError.message}`, 500);
  }

  // --- Step 8: Return clientSecret to the frontend ---
  return jsonResponse({ clientSecret: paymentIntent.client_secret });
});
