  name: 'Widget B',
  description: 'A finer widget',
  price: 2500, // €25.00
  image_url: 'https://example.com/b.jpg',
  tags: [],
  is_available: true,
};

const UNAVAILABLE_PRODUCT = {
  ...PRODUCT_A,
  id: 'prod-unavailable',
  is_available: false,
};

const VALID_CUSTOMER = {
  name: 'Jane Doe',
  email: 'jane@example.com',
  street: '123 Main St',
  city: 'Berlin',
  postal_code: '10115',
  country: 'DE',
};

const VALID_ITEMS = [
  { product_id: 'prod-a', quantity: 2 }, // 2 * 1000 = 2000
  { product_id: 'prod-b', quantity: 1 }, // 1 * 2500 = 2500
  // total = 4500
];

// ---------------------------------------------------------------------------
// Minimal stub infrastructure
// ---------------------------------------------------------------------------

interface RpcCall {
  fn: string;
  args: Record<string, unknown>;
}

interface StubState {
  products: typeof PRODUCT_A[];
  rpcCalls: RpcCall[];
  rpcErrors: Record<string, string | null>;
  rpcReturnValues: Record<string, unknown>;
  piCreated: boolean;
  piAmount: number;
  piCurrency: string;
  stripeError: string | null;
}

function buildStubs(state: StubState) {
  // Supabase client stub
  const supabaseStub = {
    from: (table: string) => ({
      select: (_cols: string) => ({
        in: (_col: string, ids: string[]) => {
          const found = state.products.filter((p) => ids.includes(p.id));
          return Promise.resolve({ data: found, error: null });
        },
      }),
      insert: (rows: unknown[]) => {
        // Capture direct inserts (not used in impl but kept for completeness)
        state.rpcCalls.push({ fn: `direct_insert_${table}`, args: { rows } });
        return Promise.resolve({ data: rows, error: null });
      },
    }),
    rpc: (fnName: string, args: Record<string, unknown>) => {
      state.rpcCalls.push({ fn: fnName, args });
      const err = state.rpcErrors[fnName] ?? null;
      const ret = state.rpcReturnValues[fnName] ?? [];
      return Promise.resolve({ data: err ? null : ret, error: err ? { message: err } : null });
    },
  };

  // Stripe stub
  const stripeStub = {
    paymentIntents: {
      create: (params: { amount: number; currency: string }) => {
        if (state.stripeError) {
          throw new Error(state.stripeError);
        }
        state.piCreated = true;
        state.piAmount = params.amount;
        state.piCurrency = params.currency;
        return Promise.resolve({
          id: 'pi_test_123',
          client_secret: 'pi_test_123_secret_abc',
        });
      },
    },
  };

  return { supabaseStub, stripeStub };
}

// ---------------------------------------------------------------------------
// Handler factory — rebuilds the handler with injected dependencies so we
// don't need actual env vars or network in tests.
// ---------------------------------------------------------------------------

type SupabaseStub = ReturnType<typeof buildStubs>['supabaseStub'];
type StripeStub = ReturnType<typeof buildStubs>['stripeStub'];

async function callHandler(
  body: unknown,
  supabase: SupabaseStub,
  stripe: StripeStub,
): Promise<Response> {
  /**
   * We inline the handler logic here rather than importing the module, because
   * Deno's module system makes it hard to swap deps mid
